// Package fields decides which units are translated. Some JSON fields hold
// identifiers or trigger labels that must stay as they are, and some single
// values are the same in KR, EN and JP; Rules.Classify tells them apart from
// text for the translator. Learn derives the field rules from the official
// packs.
//
// The rules live in two files under rules/: fields.manual.yaml is written by
// people, fields.yaml is generated by "lct fields learn". Load merges them.
package fields

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"strings"

	"gopkg.in/yaml.v3"

	"github.com/tool-jx3/limbus-translate/internal/align"
	"github.com/tool-jx3/limbus-translate/internal/units"
)

// Rule file locations, relative to the repo root.
const (
	generatedFile = "rules/fields.yaml"
	manualFile    = "rules/fields.manual.yaml"
)

// Reasons a unit is not translated; Decision.Reason holds one of them.
const (
	ReasonIdentifierField = "identifier-field" // the field is an identifier in every file
	ReasonGroupField      = "group-field"      // the field is an identifier in this group of files
	ReasonIdenticalValue  = "identical-value"  // KR, EN and JP all have this exact text
	ReasonEmpty           = "empty"            // nothing to translate
	ReasonSourceComment   = "source-comment"   // a note left in the source, not game text
	ReasonNameOnly        = "name-only"        // a note saying only the name is translated
	ReasonNotInclude      = "notinclude"       // the file is not part of the game text
)

// Group returns the group of files a file belongs to. A file in a
// subdirectory belongs to the group of its first directory ("StoryData/S001A.json"
// is in "StoryData"). Other files belong to the part of the file name before
// the first '-', '_' or digit ("BattleSpeechBubbleDlg-a1c10p3.json" is in
// "BattleSpeechBubbleDlg"); a name that starts with one of those keeps its
// whole name without ".json".
func Group(file string) string {
	if dir, _, ok := strings.Cut(file, "/"); ok {
		return dir
	}
	name := strings.TrimSuffix(file, ".json")
	if i := strings.IndexFunc(name, func(r rune) bool {
		return r == '-' || r == '_' || (r >= '0' && r <= '9')
	}); i > 0 {
		return name[:i]
	}
	return name
}

// Decision says whether a unit is translated and, if not, why.
type Decision struct {
	Translate bool
	Reason    string // one of the Reason constants; "" when Translate is true
}

// NameOnly describes the files and fields whose text is a note asking that
// only the name be translated.
type NameOnly struct {
	FileGlob string `yaml:"file_glob"` // matched against the file name without its directory
	Field    string `yaml:"field"`
	Pattern  string `yaml:"pattern"` // regular expression matched against the KR text
}

// Rules holds the merged field rules.
type Rules struct {
	identifiers     map[string]bool
	groupFields     map[string]map[string]bool
	commentPrefixes []string
	nameOnly        *NameOnly
	nameOnlyRe      *regexp.Regexp
	notInclude      string // lowercase; "" disables the check
}

// manualRules is the content of fields.manual.yaml.
type manualRules struct {
	IdentifierFields      []string            `yaml:"identifier_fields"`
	GroupFields           map[string][]string `yaml:"group_fields"`
	SourceCommentPrefixes []string            `yaml:"source_comment_prefixes"`
	NameOnly              *NameOnly           `yaml:"name_only"`
	NotIncludeSubstring   string              `yaml:"notinclude_substring"`
}

// Load reads the rules under root: rules/fields.yaml if it exists, then
// rules/fields.manual.yaml, which must exist.
func Load(root string) (*Rules, error) {
	r, err := LoadManual(root)
	if err != nil {
		return nil, err
	}
	learned, err := LoadLearned(root)
	if err != nil {
		return nil, err
	}
	for _, f := range learned.IdentifierFields {
		r.identifiers[f] = true
	}
	for g, names := range learned.GroupFields {
		r.addGroupFields(g, names)
	}
	return r, nil
}

// LoadManual reads only rules/fields.manual.yaml. Learned.Without needs it to
// keep the generated rules free of what the manual file already says.
func LoadManual(root string) (*Rules, error) {
	var m manualRules
	if _, err := decodeFile(filepath.Join(root, manualFile), &m, false); err != nil {
		return nil, err
	}
	r := &Rules{
		identifiers:     make(map[string]bool),
		groupFields:     make(map[string]map[string]bool),
		commentPrefixes: m.SourceCommentPrefixes,
		notInclude:      strings.ToLower(m.NotIncludeSubstring),
	}
	if err := checkNames(manualFile, "identifier_fields", m.IdentifierFields); err != nil {
		return nil, err
	}
	for _, f := range m.IdentifierFields {
		r.identifiers[f] = true
	}
	for g, names := range m.GroupFields {
		if g == "" {
			return nil, fmt.Errorf("fields: %s: group_fields has an empty group name", manualFile)
		}
		if err := checkNames(manualFile, "group_fields."+g, names); err != nil {
			return nil, err
		}
		r.addGroupFields(g, names)
	}
	for _, prefix := range m.SourceCommentPrefixes {
		if strings.TrimSpace(prefix) == "" {
			return nil, fmt.Errorf("fields: %s: source_comment_prefixes has an empty prefix, which would match every text", manualFile)
		}
	}
	if m.NameOnly != nil {
		if err := r.setNameOnly(*m.NameOnly); err != nil {
			return nil, fmt.Errorf("fields: %s: name_only: %w", manualFile, err)
		}
	}
	return r, nil
}

func (r *Rules) addGroupFields(group string, fields []string) {
	set := r.groupFields[group]
	if set == nil {
		set = make(map[string]bool)
		r.groupFields[group] = set
	}
	for _, f := range fields {
		set[f] = true
	}
}

func (r *Rules) setNameOnly(n NameOnly) error {
	if n.FileGlob == "" || n.Field == "" || n.Pattern == "" {
		return errors.New("file_glob, field and pattern are all required")
	}
	if _, err := path.Match(n.FileGlob, ""); err != nil {
		return fmt.Errorf("file_glob %q: %w", n.FileGlob, err)
	}
	re, err := regexp.Compile(n.Pattern)
	if err != nil {
		return fmt.Errorf("pattern: %w", err)
	}
	r.nameOnly, r.nameOnlyRe = &n, re
	return nil
}

// checkNames rejects empty names in a rule list.
func checkNames(file, key string, names []string) error {
	for _, n := range names {
		if n == "" {
			return fmt.Errorf("fields: %s: %s has an empty name", file, key)
		}
	}
	return nil
}

// decodeFile reads the YAML file p into v, rejecting unknown keys so that a
// typo does not silently drop a rule. A missing file is an error unless
// optional is set, and then found is false. An empty file leaves v as it is.
func decodeFile(p string, v any, optional bool) (found bool, err error) {
	data, err := os.ReadFile(p)
	if optional && errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("fields: %w", err)
	}
	dec := yaml.NewDecoder(bytes.NewReader(data))
	dec.KnownFields(true)
	if err := dec.Decode(v); err != nil && !errors.Is(err, io.EOF) {
		return true, fmt.Errorf("fields: parse %s: %w", p, err)
	}
	return true, nil
}

// isEmptyValue reports whether a KR text has nothing to translate: it is
// empty, only whitespace, or a single "-".
func isEmptyValue(kr string) bool {
	t := strings.TrimSpace(kr)
	return t == "" || t == "-"
}

// Classify decides whether u is translated. en and jp are the EN and JP texts
// aligned to u, or nil when the unit has none. The first rule that applies
// wins:
//
//  1. the file name contains the notinclude substring (ignoring case);
//  2. the KR text is empty, only whitespace, or "-";
//  3. the field is an identifier field;
//  4. the field is a group field of the file's group;
//  5. the KR text starts with a source comment prefix;
//  6. the file, field and KR text match the name-only rule;
//  7. EN and JP are both present and both equal the KR text.
func (r *Rules) Classify(u units.Unit, en, jp *align.LangAligned) Decision {
	skip := func(reason string) Decision { return Decision{Reason: reason} }
	switch {
	case r.notInclude != "" && strings.Contains(strings.ToLower(u.File), r.notInclude):
		return skip(ReasonNotInclude)
	case isEmptyValue(u.KR):
		return skip(ReasonEmpty)
	case r.identifiers[u.Field]:
		return skip(ReasonIdentifierField)
	case r.groupFields[Group(u.File)][u.Field]:
		return skip(ReasonGroupField)
	case r.hasCommentPrefix(u.KR):
		return skip(ReasonSourceComment)
	case r.isNameOnly(u):
		return skip(ReasonNameOnly)
	case en != nil && jp != nil && en.Value == u.KR && jp.Value == u.KR:
		return skip(ReasonIdenticalValue)
	}
	return Decision{Translate: true}
}

func (r *Rules) hasCommentPrefix(kr string) bool {
	t := strings.TrimSpace(kr)
	for _, p := range r.commentPrefixes {
		if strings.HasPrefix(t, p) {
			return true
		}
	}
	return false
}

func (r *Rules) isNameOnly(u units.Unit) bool {
	if r.nameOnly == nil || u.Field != r.nameOnly.Field {
		return false
	}
	// The pattern was checked when the rules were loaded, so Match cannot fail.
	if ok, _ := path.Match(r.nameOnly.FileGlob, path.Base(u.File)); !ok {
		return false
	}
	return r.nameOnlyRe.MatchString(u.KR)
}
